from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()  # Set of all book IDs in the library
        self.borrowed = {}  # {book_id: (user, borrow_date)}
        self.fines = {}  # {user: total_fine}
        self.user_books = {}  # {user: book_id} - tracks which book each user currently holds

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} not in library")

        # Check if user already has a book (max one book per user)
        if user in self.user_books and self.user_books[user] is not None:
            raise ValueError(f"User {user} already has a book")

        # Check if book is already borrowed
        if book_id in self.borrowed:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Record the borrowing
        self.borrowed[book_id] = (user, day)
        self.user_books[user] = book_id

        # Initialize fine for user if not exists
        if user not in self.fines:
            self.fines[user] = 0.0

    def return_book(self, user: str, book_id: str, day: date) -> float:
        # Check if user actually borrowed this book
        if book_id not in self.borrowed or self.borrowed[book_id][0] != user:
            raise ValueError(f"User {user} did not borrow book {book_id}")

        # Get borrow date
        borrow_date = self.borrowed[book_id][1]

        # Calculate due date
        due_date = borrow_date + timedelta(days=self.loan_days)

        # Calculate fine if returned after due date
        fine = 0.0
        if day > due_date:
            # Count only weekdays (Mon-Fri) between due_date + 1 and day (inclusive)
            current_date = due_date + timedelta(days=1)
            delay_days = 0
            while current_date <= day:
                # Monday=0, Sunday=6, so weekday is 0-4
                if current_date.weekday() < 5:
                    delay_days += 1
                current_date += timedelta(days=1)

            fine = delay_days * self.daily_fine

        # Update user's fine
        if user not in self.fines:
            self.fines[user] = 0.0
        self.fines[user] += fine

        # Remove from borrowed and user_books
        del self.borrowed[book_id]
        if user in self.user_books:
            self.user_books[user] = None

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.fines:
            self.fines[user] = 0.0
